typedef unsigned int nslSourceId;

class MenuEntry {};

class SoundMenuEntryFunctionFloatEdit : public MenuEntry
{
  char padding[60];
public:
  nslSourceId src;
};

class stringx
{
public:
  stringx();
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
  const char *c_str() const;
private:
  int data[4];
};

stringx operator+(const stringx &, const stringx &);

class os_file
{
public:
  enum mode { FILE_WRITE = 2 };
  os_file();
  ~os_file();
  void open(const stringx &, int);
  void write(void *, int);
  void close();
private:
  char data[144];
};

struct beach_data
{
  char name[532];
};

class game
{
  char padding[552];
  int beach_id;
public:
  int get_beach_id() { return beach_id; }
};

enum { MENUSOUND_MAXSOURCES = 32, NSL_INVALID_ID = 0, NSL_SOUNDPARAM_VOLUME = 0 };

extern beach_data BeachDataArray[];
extern game *g_game_ptr;
extern SoundMenuEntryFunctionFloatEdit *MENUSOUND_SourceEntries[MENUSOUND_MAXSOURCES];
extern const char *nslGetSourceName(nslSourceId);
extern float nslGetSourceParam(nslSourceId, int);
extern int sprintf(char *, const char *, ...);
extern unsigned int strlen(const char *);

__asm__(".equ MENUSOUND_SourceEntries,0x00579950");

bool Dump(MenuEntry *entry, int buttonid)
{
	os_file out;
	char line[80];
	int i;
	out.open((stringx(BeachDataArray[g_game_ptr->get_beach_id()].name) + stringx("SOUNDDUMP.TXT")).c_str(), os_file::FILE_WRITE);
	for (i = 0; i < MENUSOUND_MAXSOURCES; i++)
	{
		if (MENUSOUND_SourceEntries[i]->src != NSL_INVALID_ID)
		{
			sprintf(line, "%s\t%f\r\n", nslGetSourceName(MENUSOUND_SourceEntries[i]->src),
					nslGetSourceParam(MENUSOUND_SourceEntries[i]->src, NSL_SOUNDPARAM_VOLUME));
			out.write(line, strlen(line));
		}

	}

	out.close();

	return true;
}
